<?php
/**
 * Plugin Name: Lite Loader for Tin Canny (loader)
 * Description: Managed by the "Lite Loader for Tin Canny" plugin. Do not edit this file: deactivate that plugin to remove it.
 * Version:     1.0.0
 *
 * LLFTC-LOADER-SIGNATURE
 *
 * Must-use plugins load before regular plugins, so this is the only place
 * where the list of active plugins can be trimmed for a single request.
 * It only acts on Tin Canny xAPI "state" requests (the resume bookmark that
 * iSpring, Articulate and Captivate modules save every few seconds). Every
 * other request, statements included, loads WordPress exactly as before.
 */

defined( 'ABSPATH' ) || exit;

define( 'LLFTC_LOADER_VERSION', '1.0.0' );

// Kill switch: define( 'LLFTC_DISABLE', true ); in wp-config.php.
if ( defined( 'LLFTC_DISABLE' ) && LLFTC_DISABLE ) {
	return;
}

// Never interfere with WP-CLI, cron or admin screens.
if ( ( defined( 'WP_CLI' ) && WP_CLI ) || ( defined( 'DOING_CRON' ) && DOING_CRON ) || is_admin() ) {
	return;
}

/**
 * Is this request a Tin Canny xAPI state read/write?
 *
 * Tin Canny answers these inside Server::by_request() and exits without
 * touching statements, LearnDash completion or any completion hooks.
 * Requests without a stateId fall through to statement handling, so they
 * are left alone.
 *
 * @return bool
 */
function llftc_is_state_request() {
	if ( empty( $_SERVER['REQUEST_URI'] ) ) {
		return false;
	}

	$path = (string) parse_url( wp_unslash( $_SERVER['REQUEST_URI'] ), PHP_URL_PATH ); // phpcs:ignore

	// Works with subdirectory installs and index.php/ permalinks.
	if ( ! preg_match( '#/ucTinCan/(?:[^/]+/)?activities/state/?$#', $path ) ) {
		return false;
	}

	return isset( $_GET['stateId'] ) && '' !== $_GET['stateId']; // phpcs:ignore WordPress.Security.NonceVerification
}

if ( ! llftc_is_state_request() ) {
	return;
}

$llftc_settings = get_option( 'llftc_settings' );
if ( ! is_array( $llftc_settings ) || empty( $llftc_settings['enabled'] ) || empty( $llftc_settings['keep'] ) ) {
	return;
}

// Read the real list before our filter exists.
$llftc_active = (array) get_option( 'active_plugins', array() );

// The managing plugin must still be active, and so must Tin Canny and LearnDash.
$llftc_required = isset( $llftc_settings['required'] ) ? (array) $llftc_settings['required'] : array();
$llftc_main     = isset( $llftc_settings['main'] ) ? (string) $llftc_settings['main'] : '';
if ( '' === $llftc_main || ! in_array( $llftc_main, $llftc_active, true ) ) {
	return;
}
foreach ( $llftc_required as $llftc_plugin ) {
	if ( ! in_array( $llftc_plugin, $llftc_active, true ) ) {
		return;
	}
}

$GLOBALS['llftc_keep'] = array_values( array_intersect( $llftc_active, (array) $llftc_settings['keep'] ) );

// Whatever the settings say, Tin Canny and LearnDash must be in the list that loads.
foreach ( array( 'tin-canny-learndash-reporting', 'sfwd-lms' ) as $llftc_dir ) {
	$llftc_found = false;
	foreach ( $GLOBALS['llftc_keep'] as $llftc_plugin ) {
		if ( strtok( $llftc_plugin, '/' ) === $llftc_dir ) {
			$llftc_found = true;
			break;
		}
	}
	if ( ! $llftc_found ) {
		unset( $GLOBALS['llftc_keep'] );
		return;
	}
}

add_filter(
	'option_active_plugins',
	static function ( $plugins ) {
		return array_values( array_intersect( (array) $plugins, $GLOBALS['llftc_keep'] ) );
	},
	PHP_INT_MAX
);

// Safety net: the trimmed list must never be saved. update_option() treats
// "new value === current (filtered) value" as no change and writes nothing.
add_filter(
	'pre_update_option_active_plugins',
	static function ( $value, $old_value ) {
		return $old_value;
	},
	PHP_INT_MAX,
	2
);

// Optional lightweight theme, so the site theme's functions.php (which may
// depend on plugins that are not loaded now) never runs. Nothing is rendered.
$llftc_theme = isset( $llftc_settings['theme'] ) ? sanitize_key( $llftc_settings['theme'] ) : '';
if ( '' !== $llftc_theme && file_exists( WP_CONTENT_DIR . '/themes/' . $llftc_theme . '/style.css' ) ) {
	$llftc_theme_cb = static function () use ( $llftc_theme ) {
		return $llftc_theme;
	};
	add_filter( 'template', $llftc_theme_cb, PHP_INT_MAX );
	add_filter( 'stylesheet', $llftc_theme_cb, PHP_INT_MAX );
}

// Lets anyone confirm in the browser's Network tab that lite mode applied.
if ( ! headers_sent() ) {
	header( 'X-Lite-Loader: tin-canny-state; plugins=' . count( $GLOBALS['llftc_keep'] ) );
}

unset( $llftc_settings, $llftc_active, $llftc_required, $llftc_main, $llftc_plugin, $llftc_dir, $llftc_found, $llftc_theme );
